const main=document.querySelector('#main');
const state={view:'home',query:'',source:'All locations',fixed:[false,false,false],pdf:false,recipient:false,confirmed:false,done:false};
const files=[{name:'Kenya Water Supply — Proposal v3.docx',place:'OneDrive',path:'HARD / Kenya water supply / Proposals',date:'12 September 2026',note:'Working draft · 3 review items',project:'Kenya water supply'},{name:'Kenya Water Supply — Proposal v2.docx',place:'Windows',path:'Documents / Consulting / Kenya',date:'9 September 2026',note:'Earlier draft',project:'Kenya water supply'},{name:'Uganda Groundwater — Final Report.docx',place:'OneDrive',path:'HARD / Uganda groundwater / Reports',date:'3 September 2026',note:'Sample report',project:'Uganda groundwater'},{name:'Water Sector — Consultant CV.docx',place:'Windows',path:'Documents / Consulting / Profile',date:'28 August 2026',note:'Sample profile',project:'Professional profile'}];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(text){const n=document.querySelector('#notice');n.textContent=text;n.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.classList.remove('show'),6500)}
function head(label,title,sub){return `<div class="heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p class="muted">${sub}</p></div><span class="pill">Sample workspace</span></div>`}
function steps(current){return `<div class="steps">${['1 · Review document','2 · Prepare PDF','3 · Check email'].map((s,i)=>`<span class="${i===current?'current':''}">${s}</span>`).join('')}</div>`}
function home(){return `${head('A CLEARER WORKDAY','What can I help you with?','Find your files, check your work and prepare to send with confidence.')}<form id="ask" class="composer"><label class="skip" for="request">Tell HARD what you need</label><textarea id="request" placeholder="Type what you need help with…" aria-describedby="example"></textarea><div class="composer-bottom"><button type="button" id="voice">♩ Use voice</button><button class="primary" type="submit">Let’s do it <span aria-hidden="true">↗</span></button></div></form><p id="example" class="muted" style="font-size:.83rem">Try “Find my Kenya proposal” or “Check my document”.</p><div class="actions"><button class="action" data-go="review"><span class="icon">✓</span><span class="arrow">↗</span><strong>Check a document</strong><small>A fresh pair of eyes on your work</small></button><button class="action" data-go="email"><span class="icon">↗</span><span class="arrow">↗</span><strong>Prepare an email</strong><small>The right file. The right person.</small></button><button class="action" data-go="files"><span class="icon">▤</span><span class="arrow">↗</span><strong>Find a file</strong><small>Across your folders and OneDrive</small></button></div><div class="section-title"><h2>Pick up where you left off</h2><span>1 sample task</span></div><div class="resume"><div class="doc-icon">▤</div><div><h3>Kenya water supply proposal</h3><p>${state.done?'Practice submission complete · Nothing was sent':state.pdf?'Sample PDF prepared · Email needs your review':'Document review · '+state.fixed.filter(x=>!x).length+' items to check'}</p></div><button data-go="${state.pdf?'email':'review'}">Continue <span aria-hidden="true">→</span></button></div><div class="bottom-note"><b>◎</b><span>Your originals stay safe. You decide which changes to accept.</span></div>`}
function fileView(){return `${head('YOUR DOCUMENTS','Find the right file','Search sample Windows folders and OneDrive in one place.')}<label for="search"><strong>File name or project</strong></label><input class="search-input" id="search" value="${escapeHtml(state.query)}" placeholder="For example, Kenya or groundwater"><div class="filters">${['All locations','Windows','OneDrive'].map(x=>`<button data-filter="${x}" class="${state.source===x?'selected':''}" aria-pressed="${state.source===x}">${x}</button>`).join('')}</div><div class="panel" id="results">${fileResults()}</div><p class="muted">These are fictional sample files. Real folders and OneDrive will be connected in a later version.</p>`}
function fileResults(){const matches=files.filter(f=>(state.source==='All locations'||f.place===state.source)&&`${f.name} ${f.project}`.toLowerCase().includes(state.query.toLowerCase()));return `<p class="muted" role="status">${matches.length} matching ${matches.length===1?'file':'files'}</p>`+(matches.length?matches.map(f=>`<div class="file"><div class="doc-icon" aria-hidden="true">▤</div><div class="file-info"><strong>${f.name}</strong><p>${f.place} · ${f.path}<br>${f.date} · ${f.note}</p></div><button data-file="${files.indexOf(f)}">${files.indexOf(f)===0?'Review':'Details'}</button></div>`).join(''):'<div class="empty"><h3>No matching files</h3><p>Try a project name like “Kenya”, or choose all locations.</p></div>')}
const issues=[['Client name differs','The cover says “Kenya Water Partnership”, but the introduction says “Uganda Water Partnership”.','Use Kenya Water Partnership'],['Submission date is missing','The cover still contains [INSERT DATE]. The sample deadline is 18 September 2026.','Use 18 September 2026'],['Budget total needs correction','The sample line items are USD 12,000 + USD 4,000 + USD 2,000. That adds up to USD 18,000, not USD 17,000.','Use USD 18,000']];
function review(){return `${head('DOCUMENT REVIEW','A fresh pair of eyes','Kenya Water Supply — Proposal v3.docx')}${steps(state.pdf?1:0)}<div class="split"><section class="panel"><div class="section-title"><h2>Proposal preview</h2><span>Fictional sample</span></div><article class="document"><div class="doc-label">HOLLAND AFRICA RESEARCH AND DEVELOPMENT</div><h2>Kenya Water Supply<br>Technical proposal</h2><p><strong>Prepared for</strong><br>Kenya Water Partnership</p><p><strong>Submission date</strong><br>${state.fixed[1]?'18 September 2026':'[INSERT DATE]'}</p><hr><h3>1. Introduction</h3><p>HARD proposes an assessment of water supply reliability for ${state.fixed[0]?'Kenya':'Uganda'} Water Partnership, including field consultation, infrastructure review and practical recommendations.</p><h3>2. Professional fees</h3><p>Technical assessment: USD 12,000<br>Field consultation: USD 4,000<br>Reporting: USD 2,000<br><strong>Total: USD ${state.fixed[2]?'18,000':'17,000'}</strong></p></article></section><section><h2>${state.fixed.filter(x=>!x).length} items need your review</h2>${issues.map((it,i)=>`<div class="issue ${state.fixed[i]?'resolved':''}"><h3>${state.fixed[i]?'✓ ':''}${it[0]}</h3><p>${it[1]}</p><button data-fix="${i}">${state.fixed[i]?'Undo change':it[2]}</button></div>`).join('')}<div class="panel"><p class="muted">Changes apply only to this sample. Your technical judgement remains yours.</p><button class="primary full" id="pdf" ${state.fixed.every(Boolean)?'':'disabled'}>${state.pdf?'Preview sample PDF':'Approve & prepare sample PDF'}</button>${state.pdf?'<p class="success">Sample document prepared. Use the print dialog to save it as a PDF.</p><button class="full" data-go="email">Continue to email →</button>':''}</div></section></div>`}
function email(){return `${head('CHECK BEFORE SENDING','The right proposal. The right person.','Practise the final checks with a fictional contact and email.')}${steps(2)}${state.done?'<div class="success"><strong>Practice submission complete.</strong><br>No email was sent. The sample submission record is shown below.</div>':''}<div class="split"><section class="panel"><h2>Email draft</h2><label class="field">From<select id="from"><option>Gmail · Sample account (not connected)</option><option>Outlook · Sample account (not connected)</option></select></label><div class="field">To<div class="email-address" style="margin-top:10px">Mary Otieno · Kenya Water Partnership<br><strong>${state.recipient?'mary.otieno@example.org':'mary.ootieno@example.org'}</strong></div></div>${state.recipient?'<div class="success">✓ Matches the verified sample contact.</div>':'<div class="warning"><strong>One extra letter could send this to the wrong address.</strong><p style="margin:8px 0">The draft has “ootieno”. Your saved sample contact has “otieno”.</p><button id="recipient">Use verified sample contact</button></div>'}<label class="field">Subject<input id="subject" value="Kenya water supply — Technical proposal"></label><label class="field">Message<textarea id="body">Dear Mary,&#10;&#10;Please find attached my technical proposal for the Kenya water supply assessment. I would be pleased to discuss the approach and next steps.&#10;&#10;Kind regards,&#10;Holland Africa Research and Development</textarea></label></section><section><div class="panel"><h2>Attachment</h2><p><strong>Kenya Water Supply — Proposal.pdf</strong></p>${state.pdf?'<div class="success">✓ Sample proposal approved</div><button id="pdf">Preview / save sample PDF</button>':'<div class="warning">Review the document and prepare the sample PDF first.</div><button data-go="review">Review proposal →</button>'}</div><div class="panel"><h2>Final check</h2><p>${state.recipient?'✓':'○'} Recipient matches saved contact</p><p>${state.pdf?'✓':'○'} Proposal reviewed and prepared</p><div class="check"><input id="confirm" type="checkbox" ${state.confirmed?'checked':''}><label for="confirm">I have checked the recipient, message and sample attachment.</label></div><button id="send" class="primary full" ${state.recipient&&state.pdf&&state.confirmed&&!state.done?'':'disabled'}>${state.done?'Practice completed':'Complete practice submission'}</button><p class="muted" style="font-size:.8rem;margin:14px 0 0">No accounts are connected. This button records a practice submission only.</p></div>${state.done?`<div class="panel"><h2>Sample submission record</h2><p>Mary Otieno · mary.otieno@example.org</p><p>Kenya Water Supply — Proposal.pdf</p><p>${escapeHtml(state.sentAt)}</p><strong>Status: simulated, not sent</strong></div>`:''}</section></div>`}
function navigate(view){if(!['home','files','review','email'].includes(view))throw Error('Unknown view');state.view=view;render();main.focus();window.scrollTo(0,0)}
function render(){main.innerHTML=({home,file: fileView,files:fileView,review,email}[state.view])();document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false')});bind()}
function bind(){for(const id of ['subject','body','from']){const el=document.getElementById(id);if(el&&state[id]!==undefined)el.value=state[id];}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.source=b.dataset.filter;render();document.querySelector(`[data-filter="${state.source}"]`).focus()});document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{if(b.dataset.file==='0')navigate('review');else notify(files[Number(b.dataset.file)].note+'. The interactive review is available for Kenya Proposal v3.')});document.querySelectorAll('[data-fix]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.fix);state.fixed[i]=!state.fixed[i];state.pdf=false;state.confirmed=false;state.done=false;render();document.querySelector(`[data-fix="${i}"]`).focus()});const search=document.querySelector('#search');if(search)search.oninput=()=>{state.query=search.value;document.querySelector('#results').innerHTML=fileResults();document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>b.dataset.file==='0'?navigate('review'):notify('This sample has details only. Review Kenya Proposal v3 to try the workflow.'))};const ask=document.querySelector('#ask');if(ask)ask.onsubmit=e=>{e.preventDefault();const q=document.querySelector('#request').value.toLowerCase().trim();if(!q){notify('Type a request, or choose one of the three shortcuts.');return}if(/find|search|locate|folder/.test(q)){state.query=/kenya/.test(q)?'Kenya':/uganda|groundwater/.test(q)?'groundwater':'';navigate('files')}else if(/email|send|mary/.test(q))navigate('email');else if(/check|review|proposal|pdf|document/.test(q))navigate('review');else notify('This prototype supports finding files, reviewing the sample proposal and preparing an email. Choose a shortcut to try one.');};const recipient=document.querySelector('#recipient');if(recipient)recipient.onclick=()=>{state.recipient=true;state.confirmed=false;render();document.querySelector('#subject').focus()};const confirm=document.querySelector('#confirm');if(confirm)confirm.onchange=()=>{state.confirmed=confirm.checked;document.querySelector('#send').disabled=!(state.recipient&&state.pdf&&state.confirmed&&!state.done)};for(const id of ['subject','body','from']){const field=document.getElementById(id);if(field)field.oninput=()=>{state[id]=field.value;state.confirmed=false;document.querySelector('#confirm').checked=false;document.querySelector('#send').disabled=true;}}const send=document.querySelector('#send');if(send)send.onclick=()=>{if(!(state.recipient&&state.pdf&&state.confirmed))return;state.done=true;state.sentAt=new Date().toLocaleString();render();notify('Practice complete. No email was sent.')};const pdf=document.querySelector('#pdf');if(pdf)pdf.onclick=preparePdf;const voice=document.querySelector('#voice');if(voice)voice.onclick=startVoice;}
function preparePdf(){if(!state.fixed.every(Boolean))return;const w=window.open('','_blank');if(!w){notify('Allow the document preview window to open, then try again.');return}state.pdf=true;const content=`<!doctype html><html lang="en"><head><title>Kenya Water Supply — Proposal</title><style>body{font:12pt/1.7 Georgia,serif;color:#193e31;max-width:700px;margin:55px auto;padding:20px}h1{font-size:28pt}hr{border:0;border-top:1px solid #ccc}button{padding:12px;font-size:16px}@media print{button,.help{display:none}body{margin:15mm}}</style></head><body><p>HOLLAND AFRICA RESEARCH AND DEVELOPMENT</p><h1>Kenya Water Supply<br>Technical proposal</h1><p>Prepared for Kenya Water Partnership<br>18 September 2026</p><hr><h2>1. Introduction</h2><p>HARD proposes an assessment of water supply reliability for Kenya Water Partnership, including field consultation, infrastructure review and practical recommendations.</p><h2>2. Professional fees</h2><p>Technical assessment: USD 12,000<br>Field consultation: USD 4,000<br>Reporting: USD 2,000<br><strong>Total: USD 18,000</strong></p><hr><p>Fictional sample · HARD Assistant prototype</p><p class="help">Choose “Save as PDF” in your print destination to save this sample.</p><button onclick="window.print()">Print / save as PDF</button></body></html>`;w.document.write(content);w.document.close();render();notify('Sample preview opened. Choose Print / save as PDF to save a copy.');}
function startVoice(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){notify('Voice input is not supported in this browser. Typing is always available.');return}const recognition=new Speech();recognition.lang='en-GB';recognition.interimResults=false;recognition.onresult=e=>{const field=document.querySelector('#request');if(field)field.value=e.results[0][0].transcript;notify('Voice text added. Review it before continuing.')};recognition.onerror=()=>notify('Voice input could not start. Check microphone permission or type your request.');recognition.onend=()=>{const b=document.querySelector('#voice');if(b)b.textContent='♩ Use voice'};try{recognition.start();document.querySelector('#voice').textContent='Listening…'}catch{notify('Voice input is unavailable right now. Please type your request.')}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('home')};document.querySelector('#text-size').onclick=()=>{document.documentElement.classList.toggle('large');document.querySelector('#text-size').setAttribute('aria-pressed',document.documentElement.classList.contains('large'));};document.querySelector('#read').onclick=()=>{if(!('speechSynthesis'in window)){notify('Read aloud is unavailable in this browser.');return}if(speechSynthesis.speaking){speechSynthesis.cancel();return}const utterance=new SpeechSynthesisUtterance(main.innerText);utterance.rate=.9;speechSynthesis.speak(utterance)};
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_sample_files',description:'Search fictional HARD files and open the visible file search. Does not access real files.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw Error('Provide a query up to 200 characters');state.query=input.query;state.source='All locations';navigate('files');return{count:files.filter(f=>`${f.name} ${f.project}`.toLowerCase().includes(input.query.toLowerCase())).length,view:'files'}}})).catch(()=>{});}catch{}}
